 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); frame=grid[0][0]
    sep=next(c for c in range(1,w) if all(row[c]==0 for row in grid))
    left_width=sep
    cuts=[r for r in range(h) if all(v==frame for v in grid[r][:left_width])]
    def shape(cells):
        if not cells:return None
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        return frozenset((r-r0,c-c0) for r,c in cells)
    # Shapes of the zero patterns in the framed left panels select the
    # colors of right-hand objects with the same silhouette.
    objects={}
    seen=set()
    for r in range(h):
        for c in range(sep+1,w):
            color=grid[r][c]
            if color==0 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and sep<p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
                        seen.add(p); stack.append(p)
            objects[shape([(y-r,x-(sep+1)) for y,x in cells])]=color
    out=[row[:left_width] for row in grid]
    for a,b in zip(cuts,cuts[1:]):
        holes=[(r,c) for r in range(a+1,b) for c in range(left_width) if grid[r][c]==0]
        color=objects.get(shape(holes))
        if color is not None:
            for r,c in holes: out[r][c]=color
    return out
